-- NewJersey admin-controlled Print & Branding catalogue. Rerunnable, preserves existing products.
BEGIN;
ALTER TABLE public.products
 ADD COLUMN IF NOT EXISTS catalogue_department text CHECK(catalogue_department IN ('print','branding')),
 ADD COLUMN IF NOT EXISTS catalogue_enabled boolean NOT NULL DEFAULT false,
 ADD COLUMN IF NOT EXISTS catalogue_rank integer NOT NULL DEFAULT 0 CHECK(catalogue_rank BETWEEN 0 AND 99999),
 ADD COLUMN IF NOT EXISTS catalogue_quantity integer NOT NULL DEFAULT 1 CHECK(catalogue_quantity BETWEEN 1 AND 1000000),
 ADD COLUMN IF NOT EXISTS catalogue_unit text NOT NULL DEFAULT 'pieces',
 ADD COLUMN IF NOT EXISTS catalogue_options jsonb NOT NULL DEFAULT '[]'::jsonb CHECK(jsonb_typeof(catalogue_options)='array'),
 ADD COLUMN IF NOT EXISTS catalogue_topic text NOT NULL DEFAULT 'general',
 ADD COLUMN IF NOT EXISTS catalogue_legacy_id text;
CREATE UNIQUE INDEX IF NOT EXISTS catalogue_legacy_id_unique ON public.products(catalogue_legacy_id) WHERE catalogue_legacy_id IS NOT NULL;
CREATE INDEX IF NOT EXISTS products_storefront_live_idx ON public.products(catalogue_department,featured DESC,catalogue_rank,id) WHERE catalogue_enabled=true AND publication_status='published';
CREATE TABLE IF NOT EXISTS public.catalogue_enquiries(
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), customer_id uuid NOT NULL REFERENCES auth.users(id), submission_key uuid NOT NULL,
 product_id bigint NOT NULL REFERENCES public.products(id),product_name text NOT NULL,
 customer_name text NOT NULL, customer_email text, customer_phone text NOT NULL,
 brief text NOT NULL CHECK(length(brief) BETWEEN 15 AND 3000),location text NOT NULL,
 status text NOT NULL DEFAULT 'new' CHECK(status IN ('new','reviewing','quoted','closed')),
 created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(customer_id,submission_key)
);
CREATE INDEX IF NOT EXISTS catalogue_enquiries_status_idx ON public.catalogue_enquiries(status,created_at DESC);
ALTER TABLE public.catalogue_enquiries ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.catalogue_enquiries FROM PUBLIC,anon,authenticated;
GRANT ALL ON public.catalogue_enquiries TO service_role;
